function applyChrome(){document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.layout=state.layout;document.documentElement.dataset.sidebar=state.sidebar;document.documentElement.dataset.package=state.pkg||'landing'}
function render(){applyChrome();if(bannerTimer){clearInterval(bannerTimer);bannerTimer=null}app.innerHTML=state.screen==='landing'?landing():dashboard();bind();syncAuthRoot();requestAnimationFrame(()=>{observeReveals();if(state.screen==='landing'){bannerTimer=setInterval(()=>setBanner(state.landingBanner+1),6000)}})}
function updateDashboardPage(){const shell=app.querySelector('.app-shell');const content=shell?.querySelector('.dash-content');if(!shell||!content)return render();content.innerHTML=pageContent();const title=shell.querySelector('.header-left h1');if(title)title.textContent=pageTitle();shell.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));applyChrome();bindDynamicContent();requestAnimationFrame(()=>observeReveals())}
function bindDynamicContent(){document.querySelectorAll('[data-demo-toast]').forEach(b=>b.onclick=()=>toast('این بخش در نسخه Demo نمایشی است و پس از اتصال داده واقعی فعال می‌شود.'));document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{state.pkg=b.dataset.upgrade;localStorage.setItem(preferenceStorageKey('package'),state.pkg);state.page='overview';updateDashboardPage();toast('سطح Demo برای مشاهده امکانات ارتقا یافت.')});document.querySelectorAll('[data-add-file]').forEach(b=>b.onclick=()=>document.querySelector('#fileModal')?.classList.add('show'));document.querySelectorAll('[data-add-client]').forEach(b=>b.onclick=()=>document.querySelector('#clientModal')?.classList.add('show'));document.querySelectorAll('[data-add-visit]').forEach(b=>b.onclick=()=>document.querySelector('#visitModal')?.classList.add('show'));document.querySelectorAll('[data-divar]').forEach(b=>b.onclick=()=>toast('اتصال دیوار نیازمند دسترسی معتبر/API است؛ صف اتصال آماده است.'));document.querySelectorAll('[data-property-status]').forEach(el=>el.onchange=e=>updateProperty(e.target.dataset.propertyStatus,{status:e.target.value}));document.querySelectorAll('[data-property-client]').forEach(el=>el.onchange=e=>updateProperty(e.target.dataset.propertyClient,{client_id:e.target.value||null}))}
function updateThemeUI(){applyChrome();document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.innerHTML=icon(state.theme==='dark'?'sun':'moon'));updateCustomizeUI()}
function updateCustomizeUI(){document.querySelectorAll('[data-set-theme]').forEach(b=>b.classList.toggle('selected',b.dataset.setTheme===state.theme));document.querySelectorAll('[data-set-layout]').forEach(b=>b.classList.toggle('selected',b.dataset.setLayout===state.layout));document.querySelectorAll('[data-set-sidebar]').forEach(b=>b.classList.toggle('selected',b.dataset.setSidebar===state.sidebar))}

function landing(){
  const accountActions = state.session
    ? `<button class="btn btn-primary btn-sm" data-go-dashboard>داشبورد من ${icon('arrow')}</button>`
    : `<button class="btn btn-ghost btn-sm" data-auth="login">ورود</button><button class="btn btn-primary btn-sm" data-auth="signup">ساخت حساب ${icon('arrow')}</button>`;
  const cards = Object.values(packages).map(p=>`<article class="package-card ${p.key}" style="--accent:${p.accent}" data-pkg="${p.key}">
    <div class="package-line"></div><div class="package-top"><span class="package-index">${p.key==='bronze'?'01':p.key==='silver'?'02':p.key==='gold'?'03':'04'}</span><span class="package-eyebrow">${p.eyebrow}</span></div>
    <div class="package-symbol">${p.key==='bronze'?icon('home'):p.key==='silver'?icon('layers'):p.key==='gold'?icon('trend'):icon('diamond')}</div>
    <h3>${p.title}</h3><div class="price"><b>${p.price}</b><span>${p.unit}</span></div>
    <div class="package-features">${p.features.slice(0,4).map(f=>`<span>${icon(f[0])}${esc(f[1])}</span>`).join('')}</div>
    <button type="button" class="package-cta">ورود به تجربه ${icon('arrow')}</button>
  </article>`).join('');
  return `<div class="site-shell landing-shell">
    <header class="site-nav"><a class="brand" href="#"><img src="/luckyweb-logo.png" alt="Lucky Web"><span><b>Lucky Web</b><small>Real Estate Operating System</small></span></a><nav><button type="button" data-scroll="packages">پکیج‌ها</button><button type="button" data-scroll="experience">تجربه محصول</button><button type="button" data-catalog>کاتالوگ</button></nav><div class="nav-tools"><button type="button" class="icon-button theme-toggle" data-theme-toggle title="تغییر تم">${icon(state.theme==='dark'?'sun':'moon')}</button>${accountActions}</div></header>
    <main>
      <section class="hero-section" data-reveal><div class="hero-copy"><span class="eyebrow-pill"><i></i> اکوسیستم هوشمند دفاتر املاک</span><h1>دفتر املاک را از یک <em>نرم‌افزار</em> به یک اکوسیستم تبدیل کنید.</h1><p>پلتفرمی برای پاسخگویی، بازدید، فایل‌یابی، تولید محتوا و مدیریت رشد؛ با تجربه‌ای که بر اساس سطح سرویس شما شکل می‌گیرد.</p><div class="hero-actions"><button class="btn btn-primary btn-lg" data-scroll="packages">شروع تجربه لایو ${icon('arrow')}</button><button class="btn btn-ghost btn-lg" data-catalog>مشاهده کاتالوگ</button></div><div class="trust-row"><div><strong>۴</strong><span>سطح سرویس</span></div><div><strong>۱</strong><span>اکوسیستم یکپارچه</span></div><div><strong>∞</strong><span>قابل توسعه</span></div></div></div>
      <div class="hero-stage"><div class="hero-image" style="background-image:url('${imageUrls.hero}')"><div class="image-overlay"></div><span class="image-tag">Luxury Operations</span></div><div class="hero-product-card"><div class="mini-brand"><span class="dot"></span><b>Lucky Web</b><small>PRODUCT PREVIEW</small></div><div class="mini-chart"><div><span>محیط آماده ورود داده</span><b>۰</b></div><div class="chart-bars">${[34,52,43,68,58,79,91].map(h=>`<i style="height:${h}%"></i>`).join('')}</div></div><div class="mini-kpis"><span><small>ملک</small><b>۰</b></span><span><small>بازدید</small><b>۰</b></span><span><small>اعضا</small><b>۰</b></span></div></div></div></section>
      <section class="landing-banners" data-reveal><div class="banner-rail"><div class="banner-slide active" style="background-image:url('${imageUrls.hero}')"><div><span>01 · WORKSPACE</span><h3>یک محیط اختصاصی برای هر دفتر</h3><p>از اولین ورود، داده‌ها از صفر شروع می‌شوند و اطلاعات واقعی کسب‌وکار شما وارد سیستم می‌شود.</p></div></div><div class="banner-slide" style="background-image:url('${imageUrls.interior}')"><div><span>02 · CONTENT</span><h3>تولید محتوای حرفه‌ای برای املاک</h3><p>در نسخه نهایی، فایل‌های واقعی دفتر به سناریو، تصویر و ویدئو تبدیل می‌شوند.</p></div></div><div class="banner-slide" style="background-image:url('${imageUrls.office}')"><div><span>03 · OPERATIONS</span><h3>مدیریت عملیات در یک داشبورد</h3><p>بازدید، فایل، تیم، محتوا و رشد در یک فضای کاری یکپارچه قابل مشاهده خواهند بود.</p></div></div><div class="banner-slide" style="background-image:url('${imageUrls.villa}')"><div><span>04 · EXPERIENCE</span><h3>تجربه‌ای متناسب با پکیج انتخابی</h3><p>هر پکیج هویت بصری، سطح امکانات و مسیر رشد مخصوص خودش را دارد.</p></div></div><button type="button" class="banner-nav prev" data-banner-prev>${icon('arrow')}</button><button type="button" class="banner-nav next" data-banner-next>${icon('arrow')}</button><div class="banner-dots">${[0,1,2,3].map(i=>`<button type="button" data-banner-dot="${i}" class="${i===0?'active':''}"></button>`).join('')}</div></div></section>
      <section class="image-strip" data-reveal><div class="image-strip-card" style="background-image:url('${imageUrls.interiorEmpty}')"><span>01 · INTERIOR</span><b>فضاهای لوکس، روایت بصری قدرتمند</b></div><div class="image-strip-card" style="background-image:url('${imageUrls.brand}')"><span>02 · BRAND</span><b>برندینگ برای بازار املاک مدرن</b></div><div class="image-strip-card" style="background-image:url('${imageUrls.villa}')"><span>03 · PROPERTY</span><b>هر فایل، یک تجربه قابل ارائه</b></div><div class="image-strip-card" style="background-image:url('${imageUrls.interior}')"><span>04 · CONTENT</span><b>محتوا در دل جریان فروش</b></div></section>
      <section id="experience" class="experience-section" data-reveal><div class="section-heading"><span class="section-kicker">CATALOG → PRODUCT</span><h2>کاتالوگ را به یک تجربه زنده تبدیل کرده‌ایم.</h2><p>هر سطح سرویس یک تجربه Dashboard اختصاصی دارد؛ قابلیت‌ها بر اساس کاتالوگ واقعی باز می‌شوند و قابلیت‌های بالاتر در وضعیت Upgrade باقی می‌مانند.</p></div><div class="experience-flow"><div><span>01</span><b>معرفی</b><small>روایت محصول</small></div><i></i><div><span>02</span><b>انتخاب</b><small>سطح سرویس</small></div><i></i><div><span>03</span><b>ورود</b><small>حساب کاربری</small></div><i></i><div><span>04</span><b>تجربه</b><small>داشبورد شخصی</small></div></div></section>
      <section id="packages" class="packages-section" data-reveal><div class="section-heading split"><div><span class="section-kicker">PACKAGE ECOSYSTEM</span><h2>چهار سطح، چهار مدل رشد.</h2></div><span class="section-note">کارت‌ها را انتخاب کنید تا بعد از ورود، تجربه همان سطح را ببینید.</span></div><div class="package-grid">${cards}</div></section>
      <section class="visual-section" data-reveal><div class="visual-copy"><span class="section-kicker">DESIGNED FOR REAL ESTATE</span><h2>عمق محصول، پشت سادگی رابط پنهان شده است.</h2><p>در نگاه اول مینیمال است؛ با تعامل، داشبوردها، گزارش‌ها، گردش کار و لایه‌های مدیریتی خودش را نشان می‌دهند.</p><ul><li>${icon('check')} ساختار مبتنی بر امکانات واقعی کاتالوگ</li><li>${icon('check')} داده‌های Demo اختصاصی هر حساب</li><li>${icon('check')} Theme و Layout قابل شخصی‌سازی</li></ul></div><div class="visual-mosaic"><div style="background-image:url('${imageUrls.villa}')"></div><div style="background-image:url('${imageUrls.interior}')"></div><div style="background-image:url('${imageUrls.office}')"></div></div></section>
      <section class="catalog-banner" data-reveal><div><span class="section-kicker">OFFICIAL CATALOG</span><h2>جزئیات سرویس‌ها را از منبع اصلی ببینید.</h2><p>PDF کاتالوگ در پروژه قرار گرفته و از همین محیط قابل مشاهده است.</p></div><button class="btn btn-primary" data-catalog>باز کردن کاتالوگ ${icon('arrow')}</button></section>
    </main><footer><span>Lucky Web · Real Estate SaaS</span><span>Demo environment · Customer data excluded</span></footer>${catalogModal()}
  </div>`;
}

function catalogModal(){return `<div class="modal-backdrop ${state.catalog?'show':''}" data-close-modal="catalog"><section class="modal-card catalog-modal" role="dialog" aria-modal="true"><header><div><span class="section-kicker">OFFICIAL PDF</span><h3>کاتالوگ Lucky Web</h3></div><button class="icon-button" data-close-catalog>${icon('x')}</button></header><iframe src="/catalog.pdf#toolbar=1&navpanes=0" title="Lucky Web Catalog"></iframe></section></div>`}
function authModal(){return `<div class="modal-backdrop show" data-close-modal="auth"><section class="modal-card auth-modal" role="dialog" aria-modal="true" aria-labelledby="authTitle"><button type="button" class="modal-close icon-button" data-close-auth aria-label="بستن">${icon('x')}</button><div class="auth-brand"><img src="/luckyweb-logo.png" alt="Lucky Web"><span><b>Lucky Web</b><small>Secure workspace</small></span></div><div class="auth-copy"><span class="section-kicker">${state.authMode==='signup'?'CREATE WORKSPACE':'WELCOME BACK'}</span><h2 id="authTitle">${state.authMode==='signup'?'فضای کاری خودت را بساز.':'به فضای کاری Lucky Web وارد شو.'}</h2><p>${state.authMode==='signup'?'حساب شما یک فضای Demo اختصاصی با داده‌های مستقل ایجاد می‌کند.':'جلسه امن شما از طریق Supabase Auth مدیریت می‌شود.'}</p></div>${!supabase?`<div class="setup-warning"><strong>اتصال Supabase هنوز تنظیم نشده است.</strong><span>فایل <code>.env</code> را از روی <code>.env.example</code> بساز و VITE_SUPABASE_URL و VITE_SUPABASE_PUBLISHABLE_KEY را وارد کن.</span></div>`:''}<form id="authForm" novalidate><label>ایمیل<input name="email" type="email" autocomplete="email" required placeholder="name@agency.ir"></label>${state.authMode==='signup'?`<label>نام نمایشی<input name="name" autocomplete="name" required placeholder="مدیریت دفتر املاک"></label>`:''}<label>رمز عبور<input name="password" type="password" minlength="8" autocomplete="${state.authMode==='signup'?'new-password':'current-password'}" required placeholder="حداقل ۸ کاراکتر"></label><button class="btn btn-primary btn-lg full" type="submit">${state.authMode==='signup'?'ساخت حساب امن':'ورود امن'} ${icon('arrow')}</button></form><div class="auth-switch">${state.authMode==='signup'?'حساب دارید؟':'حساب ندارید؟'} <button type="button" data-auth-switch="${state.authMode==='signup'?'login':'signup'}">${state.authMode==='signup'?'ورود':'ساخت حساب'}</button></div><div class="form-message" id="authMessage" role="status" aria-live="polite"></div></section></div>`}
function syncAuthRoot(){
  if(!authRoot)return;
  if(!state.authOpen){
    if(authRoot.childElementCount)authRoot.innerHTML='';
    authRoot.removeAttribute('data-auth-mode');
    return;
  }
  const mountedMode=authRoot.dataset.authMode;
  if(!authRoot.querySelector('#authForm') || mountedMode!==state.authMode){
    authRoot.innerHTML=authModal();
    authRoot.dataset.authMode=state.authMode;
    bindAuth();
  }
}
function renderAuth(){syncAuthRoot()}
function bindAuth(){
  const form=authRoot.querySelector('#authForm');
  if(form){
    form.addEventListener('submit',authSubmit);
    form.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeAuth()}});
  }
  authRoot.querySelector('[data-close-auth]')?.addEventListener('click',e=>{e.preventDefault();closeAuth()});
  authRoot.querySelector('[data-auth-switch]')?.addEventListener('click',e=>{
    e.preventDefault();
    state.authMode=authRoot.querySelector('[data-auth-switch]').dataset.authSwitch;
    state.authMessage='';
    renderAuth();
    requestAnimationFrame(()=>authRoot.querySelector('input')?.focus());
  });
  authRoot.querySelector('[data-close-modal="auth"]')?.addEventListener('click',e=>{if(e.target===e.currentTarget){e.preventDefault();closeAuth()}});
}
function openAuth(mode='login',pendingPkg=null){state.authMode=mode;state.pendingPkg=pendingPkg;state.authMessage='';state.authOpen=true;renderAuth();requestAnimationFrame(()=>authRoot.querySelector('input')?.focus())}
function closeAuth(){state.authOpen=false;state.authMessage='';renderAuth()}
function setAuthMessage(message,type='error'){const el=authRoot?.querySelector('#authMessage');if(!el)return;el.textContent=message||'';el.dataset.type=type;el.classList.toggle('visible',Boolean(message))}
function setAuthLoading(loading){const root=authRoot;if(!root)return;root.querySelectorAll('input,[data-auth-switch],[data-close-auth]').forEach(el=>el.disabled=loading);const btn=root.querySelector('#authForm button[type="submit"]');if(btn){btn.disabled=loading;btn.innerHTML=loading?'در حال برقراری اتصال…':(state.authMode==='signup'?'ساخت حساب امن':'ورود امن')+' '+icon('arrow')}}
async function authSubmit(e){e.preventDefault();e.stopPropagation();const form=e.currentTarget;if(!form?.isConnected)return;if(!supabase){setAuthMessage('ابتدا اتصال Supabase را در فایل .env تنظیم کنید.');return}const fd=new FormData(form),email=String(fd.get('email')||'').trim(),password=String(fd.get('password')||''),name=String(fd.get('name')||'').trim();if(!email||!email.includes('@')){setAuthMessage('لطفاً یک ایمیل معتبر وارد کنید.');return}if(password.length<8){setAuthMessage('رمز عبور باید حداقل ۸ کاراکتر باشد.');return}if(state.authMode==='signup'&&!name){setAuthMessage('نام نمایشی را وارد کنید.');return}setAuthLoading(true);setAuthMessage('');try{if(state.authMode==='signup'){const {data,error}=await supabase.auth.signUp({email,password,options:{data:{full_name:name}}});if(error)throw error;if(data.session){state.session=data.session;state.screen='dashboard';state.pkg=state.pendingPkg||state.pkg||'bronze';localStorage.setItem(preferenceStorageKey('package'),state.pkg);state.pendingPkg=null;closeAuth();await loadWorkspace();}else{setAuthLoading(false);setAuthMessage('حساب ساخته شد. ایمیل تأیید را بررسی کنید، سپس وارد شوید.','success')}}else{const {data,error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;state.session=data.session;state.screen='dashboard';state.pkg=state.pendingPkg||state.pkg||'bronze';state.pendingPkg=null;closeAuth();await loadWorkspace()}}catch(err){setAuthLoading(false);setAuthMessage(err.message||'عملیات احراز هویت ناموفق بود.')}}

function dashboard(){
  const p=pkg();
  return `<div class="app-shell ${p.key}"><aside class="sidebar"><div class="side-brand"><img src="/luckyweb-logo.png" alt="Lucky Web"><div><b>Lucky Web</b><small>${p.title} · Workspace</small></div><button class="icon-button sidebar-collapse" data-customize title="شخصی‌سازی منو">${icon('settings')}</button></div><div class="side-package"><span>${p.eyebrow}</span><b>${p.title}</b><small>${p.price} · ${p.unit}</small></div><nav>${navItems.map(([key,ico,label,feature])=>{const locked=feature!=='overview'&&!has(feature);return `<button class="nav-item ${state.page===key?'active':''} ${locked?'locked':''}" data-page="${key}" ${locked?'aria-label="نیازمند ارتقا"':''}><i>${icon(ico)}</i><span>${label}</span>${locked?`<em>${icon('lock')}</em>`:''}</button>`}).join('')}</nav><div class="side-footer"><button data-back>${icon('home')} صفحه اصلی</button><button data-customize>${icon('settings')} Customize Experience</button><small>داده‌ها به حساب شما متصل‌اند.</small></div></aside><div class="mobile-backdrop"></div><main class="dash-main"><header class="dash-header"><div class="header-left"><button class="mobile-menu icon-button" data-mobile title="باز کردن منو">${icon('menu')}</button><button class="home-button icon-button" data-home title="صفحه اصلی">${icon('home')}</button><div><span class="section-kicker">REAL ESTATE OPERATING SYSTEM</span><h1>${pageTitle()}</h1></div></div><div class="header-right"><div class="search-box">${icon('search')}<input placeholder="جستجو در فضای کاری..." aria-label="جستجو"></div><button class="icon-button" data-catalog title="کاتالوگ">${icon('files')}</button><button class="icon-button theme-toggle" data-theme-toggle title="تغییر تم">${icon(state.theme==='dark'?'sun':'moon')}</button><button class="user-menu" data-profile><span class="avatar">${avatarLetters()}</span><span><b>${esc(state.profile?.full_name || 'مدیر فضای کاری')}</b><small>${esc(state.session?.user?.email || 'workspace')}</small></span></button></div></header><div class="dash-content">${pageContent()}</div></main>${catalogModal()}${customizeModal()}${profileModal()}${fileModal()}${clientModal()}${visitModal()}</div>`;
}
function pageTitle(){return ({overview:'داشبورد مدیریتی',rag:'پاسخگویی هوشمند',visits:'مدیریت بازدید',files:'فایل‌یابی و گزارش',content:'استودیو محتوا',beforeafter:'سیستم قبل و بعد',seo:'مرکز سئو و رشد',management:'مدیریت نیروهای املاک',assistant:'دستیار هوشمند مدیریتی',automation:'اتوماسیون‌های اختصاصی',persona:'شخصیت مجازی','360pro':'نمای ۳۶۰ درجه'})[state.page]||'داشبورد'}
function avatarLetters(){const n=state.profile?.full_name||'LW';return n.split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase().slice(0,2)}
function pageContent(){if(state.loading)return loadingPage();if(state.page==='overview')return overviewPage();if(!has(state.page))return lockedPage(state.page);const map={rag:ragPage,visits:visitsPage,files:filesPage,content:contentPage,beforeafter:beforeAfterPage,seo:seoPage,management:managementPage,assistant:assistantPage,automation:automationPage,persona:personaPage,'360pro':tourPage};const out=map[state.page]?.() || featureGeneric(featureByKey(state.page));return out+howItWorks(state.page);}
function topIntro(label,title,desc){return `<div class="page-intro" data-reveal><div><span class="section-kicker">${esc(label)}</span><h2>${esc(title)}</h2><p>${esc(desc)}</p></div><div class="live-badge"><i></i> Live Workspace</div></div>`}
function fmt(v){return Number(v||0).toLocaleString('fa-IR')}
function fmtPercent(v){return `${Number(v||0).toLocaleString('fa-IR',{maximumFractionDigits:1})}%`}
function fmtMoney(v){const n=Number(v||0); if(n===0)return '۰'; if(n>=1000000000)return `${(n/1000000000).toLocaleString('fa-IR',{maximumFractionDigits:1})} میلیارد`; if(n>=1000000)return `${(n/1000000).toLocaleString('fa-IR',{maximumFractionDigits:1})} میلیون`; return n.toLocaleString('fa-IR')}

function statCard(label,value,delta,ico='trend'){return `<div class="stat-card" data-reveal><div class="stat-icon">${icon(ico)}</div><div><small>${label}</small><strong>${value}</strong><span>${delta}</span></div></div>`}
function overviewPage(){const p=pkg();return `${topIntro(`${p.title} PACKAGE`,'تصویر کامل عملیات دفتر املاک','یک نمای مدیریتی از تجربه این سطح سرویس؛ فضای کاری عمداً خالی است تا اطلاعات خام واقعی دفتر شما وارد شود.')}<div class="dashboard-banner" data-reveal><div><span class="eyebrow-pill">سطح فعال · ${p.title}</span><h3>یک فضای کاری که با مدل رشد دفتر شما تغییر می‌کند.</h3><p>${p.features.length} قابلیت از کاتالوگ در این سطح فعال است. قابلیت‌های بالاتر در مسیر Upgrade قابل مشاهده‌اند.</p><div class="banner-actions"><button class="btn btn-primary" data-customize>شخصی‌سازی تجربه ${icon('settings')}</button><button class="btn btn-ghost" data-catalog>کاتالوگ</button></div></div><div class="banner-metric"><b>${p.features.length}</b><span>قابلیت فعال</span><i></i></div></div><div class="stats-grid kpi-grid">${statCard('فایل‌های فعال',fmt(state.kpis.properties),'از داده واقعی Workspace','home')}${statCard('بازدیدهای آینده',fmt(state.kpis.visits),'رزروهای ثبت‌شده','calendar')}${statCard('سرنخ‌های فعال',fmt(state.kpis.leads),'فرصت‌های فروش','users')}${statCard('قراردادهای موفق',fmt(state.kpis.deals),'معاملات ثبت‌شده','check')}${statCard('ارزش Pipeline',fmtMoney(state.kpis.pipeline),'مجموع فرصت‌های باز','trend')}${statCard('نرخ تبدیل',fmtPercent(state.kpis.conversion),'سرنخ به قرارداد','target')}</div><div class="content-grid two"><section class="panel" data-reveal><div class="panel-head"><div><h3>فعالیت‌های اخیر</h3><small>داده‌های این حساب</small></div><button class="small-btn">مشاهده همه ${icon('arrow')}</button></div><div class="activity-list">${activityRows()}</div></section><section class="panel" data-reveal><div class="panel-head"><div><h3>امکانات پکیج</h3><small>${p.features.length} قابلیت فعال از کاتالوگ</small></div></div><div class="feature-list">${p.features.map(f=>`<div><span class="feature-icon">${icon(f[0])}</span><div><b>${esc(f[1])}</b><small>${esc(f[2])}</small></div><span class="checkmark">${icon('check')}</span></div>`).join('')}</div></section></div>`}
function activityRows(){if(!state.activity.length)return `<div class="empty-state"><strong>هنوز فعالیتی ثبت نشده است.</strong><span>بعد از ورود اولین داده واقعی، رویدادهای این حساب اینجا نمایش داده می‌شوند.</span></div>`;return state.activity.map((a,i)=>`<div class="activity"><span class="activity-dot d${i}"></span><div><b>${esc(a[0])}</b><small>${esc(a[1])}</small></div><time>${esc(a[2])}</time></div>`).join('')}
function lockedPage(key){const f=featureByKey(key);const upgrade=['automation','persona','360pro','seo-growth','ai-management'].includes(key)?'انحصاری':'طلایی';return `<div class="locked-page" data-reveal><div class="lock-orb">${icon('lock')}</div><span class="section-kicker">UPGRADE AVAILABLE</span><h2>${esc(f[1])}</h2><p>این قابلیت در کاتالوگ برای پکیج فعلی فعال نیست. برای نمایش تجربه کامل آن، سطح سرویس را ارتقا دهید.</p><div class="upgrade-card"><div><span>پیشنهاد ارتقا</span><b>پکیج ${upgrade}</b><small>بدون از دست دادن داده‌های فضای کاری.</small></div><button class="btn btn-primary" data-upgrade="${upgrade==='انحصاری'?'exclusive':'gold'}">مشاهده پکیج ${upgrade} ${icon('arrow')}</button></div></div>`}
function featureGeneric(f){return `${topIntro('PACKAGE FEATURE',f[1],f[2])}<div class="feature-workspace" data-reveal><div class="feature-hero"><div class="big-feature-icon">${icon(f[0])}</div><div><span class="live-badge"><i></i> فعال در Workspace</span><h3>${esc(f[1])}</h3><p>${esc(f[2])}</p></div></div><div class="workspace-grid"><div class="metric-block"><small>وضعیت سرویس</small><strong>آماده</strong><span>همگام با ${pkg().title}</span></div><div class="metric-block"><small>داده واقعی</small><strong>۰</strong><span>در انتظار ورود</span></div><div class="metric-block"><small>آخرین بروزرسانی</small><strong>—</strong><span>پس از اولین داده</span></div></div></div>`}
function ragPage(){return `${topIntro('RAG ASSISTANT','پاسخگویی خودکار هوشمند','در نسخه نهایی، پاسخ‌ها از دانش تأییدشده دفتر و داده‌های واقعی Workspace بازیابی می‌شوند.')}<div class="rag-layout"><section class="panel chat-panel" data-reveal><div class="chat-head"><div class="ai-avatar">${icon('spark')}</div><div><b>Lucky Assistant</b><small>Workspace context</small></div><span class="live-badge"><i></i> Ready</span></div><div class="empty-state"><strong>هنوز دانش یا سؤال ثبت نشده است.</strong><span>فایل‌ها، FAQ و اطلاعات تأییدشده دفتر در نسخه نهایی منبع پاسخ خواهند بود.</span></div><div class="chat-input"><input placeholder="سؤال خود را بعد از ورود داده بنویسید..."/><button class="btn btn-primary" type="button" data-demo-toast>ارسال</button></div></section><section class="panel" data-reveal><div class="panel-head"><div><h3>منابع پاسخ</h3><small>در نسخه نهایی</small></div></div><div class="empty-state"><strong>منبعی متصل نیست.</strong><span>با اتصال پایگاه دانش، سیستم منابع استفاده‌شده در هر پاسخ را نمایش می‌دهد.</span></div></section></div>`}

function jalaliDate(ts){try{return new Intl.DateTimeFormat('fa-IR-u-ca-persian',{year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(ts))}catch{return '—'}}
function jalaliToGregorian(jy,jm,jd){let gy=jy>979?1600:621;let y=jy>979?jy-979:jy;let days=365*y+Math.floor(y/33)*8+Math.floor((y%33+3)/4)+78+jd+(jm<7?(jm-1)*31:(jm-7)*30+186);gy+=400*Math.floor(days/146097);days%=146097;if(days>36524){gy+=100*Math.floor(--days/36524);days%=36524;if(days>=365)days++}gy+=4*Math.floor(days/1461);days%=1461;if(days>365){gy+=Math.floor((days-1)/365);days=(days-1)%365}let gd=days+1;const leap=((gy%4===0&&gy%100!==0)||gy%400===0);const md=[0,31,leap?29:28,31,30,31,30,31,31,30,31,30,31];let gm=1;while(gd>md[gm]){gd-=md[gm];gm++}return {gy,gm,gd}}
function visitsPage(){const rows=state.visits;return `${topIntro('SMART VISITS','مدیریت بازدید','تاریخ‌ها با تقویم ایرانی نمایش داده می‌شوند و هر بازدید به ملک و مشتری متصل است.')}<div class="stats-grid">${statCard('بازدیدهای آینده',String(rows.filter(v=>new Date(v.scheduled_at)>=new Date()&&v.status!=='cancelled').length),'داده واقعی','calendar')}${statCard('تأییدشده',String(rows.filter(v=>v.status==='confirmed').length),'بازدیدهای قطعی','check')}${statCard('مشتریان',String(state.clients.length),'پایگاه مشتریان','users')}${statCard('املاک',String(state.properties.length),'فایل‌های Workspace','home')}</div><div class="content-grid two"><section class="panel" data-reveal><div class="calendar-head"><div><h3>بازدیدها</h3><small>تاریخ شمسی · اتصال مشتری و ملک</small></div><button class="btn btn-primary" type="button" data-add-visit>افزودن بازدید ${icon('plus')}</button></div>${rows.length?`<div class="visit-list">${rows.map(v=>{const p=state.properties.find(x=>x.id===v.property_id);const c=state.clients.find(x=>x.id===v.client_id);return `<div class="visit-row"><div class="visit-time"><b>${jalaliDate(v.scheduled_at)}</b><small>${new Date(v.scheduled_at).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit'})}</small></div><div><b>${esc(p?.title||'بدون ملک')}</b><small>${esc(c?.name||'بدون مشتری')} · ${esc(v.notes||'بدون توضیح')}</small></div><span class="status ${v.status}">${v.status==='confirmed'?'تأیید شده':v.status==='completed'?'انجام شد':v.status==='cancelled'?'لغو شده':'در انتظار'}</span></div>`}).join('')}</div>`:`<div class="empty-state"><strong>هنوز بازدیدی ثبت نشده است.</strong><span>اولین بازدید را ثبت کن تا تقویم واقعی Workspace شکل بگیرد.</span></div>`}</section><section class="panel" data-reveal><div class="panel-head"><div><h3>مشتریان</h3><small>پایگاه مشتریان واقعی Workspace</small></div><button class="btn btn-ghost" type="button" data-add-client>مشتری جدید ${icon('plus')}</button></div>${state.clients.length?`<div class="client-list">${state.clients.map(c=>`<div class="client-row"><div class="avatar">${esc((c.name||'?').slice(0,1))}</div><div><b>${esc(c.name)}</b><small>${esc(c.phone||'بدون شماره')} · ${esc(c.requirements||'بدون نیاز ثبت‌شده')}</small></div><span>${esc(c.budget||'—')}</span></div>`).join('')}</div>`:`<div class="empty-state"><strong>هنوز مشتری ثبت نشده است.</strong><span>مشخصات مشتری را اضافه کن تا در مذاکره، بازدید و فایل‌یابی قابل انتخاب باشد.</span></div>`}</section></div>`}
function filesPage(){const counts={active:state.properties.filter(p=>p.status==='active').length,negotiation:state.properties.filter(p=>p.status==='negotiation').length,sold:state.properties.filter(p=>p.status==='sold').length};return `${topIntro('FILE FINDER','فایل‌یابی و گزارش','فایل‌های واقعی Workspace را مدیریت کن؛ وضعیت هر ملک و مشتری مذاکره‌شونده مستقیماً در دیتابیس ثبت می‌شود.')}<div class="content-grid two"><section class="panel divar-connect" data-reveal><div class="panel-head"><div><span class="section-kicker">DIVAR CONNECT</span><h3>اتصال به اپلیکیشن دیوار</h3><small>برای پکیج‌های دارای فایل‌یابی</small></div><span class="live-badge"><i></i> آماده اتصال</span></div><div class="divar-visual"><div class="divar-orb">D</div><div><b>فایل‌یابی خودکار</b><p>پس از اتصال معتبر، نیازهای مشتری به موتور جستجو داده می‌شود تا فایل‌های مناسب را پیدا و برای پیگیری وارد Workspace کند.</p></div></div><div class="divar-steps"><span>۰۱ · اتصال حساب</span><span>۰۲ · تعریف نیاز مشتری</span><span>۰۳ · جستجوی خودکار</span><span>۰۴ · ورود فایل مرتبط</span></div><button class="btn btn-primary" type="button" data-divar>اتصال دیوار ${icon('arrow')}</button></section><section class="panel" data-reveal><div class="panel-head"><div><h3>مشتریان و نیازها</h3><small>مشتری را برای فایل‌یابی و مذاکره انتخاب کن.</small></div><button class="btn btn-ghost" type="button" data-add-client>مشتری جدید ${icon('plus')}</button></div>${state.clients.length?`<div class="client-list">${state.clients.map(c=>`<div class="client-row"><div class="avatar">${esc((c.name||'?').slice(0,1))}</div><div><b>${esc(c.name)}</b><small>${esc(c.requirements||'نیاز ثبت نشده')}</small></div><span>${esc(c.budget||'—')}</span></div>`).join('')}</div>`:`<div class="empty-state"><strong>هنوز مشتری ندارید.</strong><span>ابتدا مشتری و نیاز او را ثبت کنید.</span></div>`}</section></div><div class="stats-grid">${statCard('فایل فعال',String(counts.active),'ملک‌های قابل ارائه','files')}${statCard('در مذاکره',String(counts.negotiation),'ملک‌های در مذاکره','users')}${statCard('فروخته‌شده',String(counts.sold),'معاملات بسته‌شده','check')}${statCard('کل فایل‌ها',String(state.properties.length),'داده واقعی','home')}</div><section class="panel table-panel" data-reveal><div class="panel-head"><div><h3>فایل‌های Workspace</h3><small>وضعیت را مستقیم تغییر بده.</small></div><button type="button" class="btn btn-ghost" data-add-file>افزودن فایل ${icon('plus')}</button></div>${state.properties.length?`<div class="table-scroll"><table><thead><tr><th>ملک</th><th>متراژ</th><th>قیمت</th><th>وضعیت</th><th>مشتری مذاکره</th></tr></thead><tbody>${state.properties.map(p=>{const c=state.clients.find(x=>x.id===p.client_id);return `<tr><td><b>${esc(p.title)}</b></td><td>${esc(p.area)}</td><td>${esc(p.price)}</td><td><select class="status-select" data-property-status="${p.id}"><option value="active" ${p.status==='active'?'selected':''}>فعال</option><option value="negotiation" ${p.status==='negotiation'?'selected':''}>در مذاکره</option><option value="sold" ${p.status==='sold'?'selected':''}>فروخته شد</option></select></td><td><select class="status-select" data-property-client="${p.id}"><option value="">${p.status==='negotiation'?'انتخاب مشتری':'بدون مشتری'}</option>${state.clients.map(x=>`<option value="${x.id}" ${p.client_id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty-state"><strong>هنوز ملکی ثبت نشده است.</strong><span>اطلاعات خام ملک‌ها را وارد کنید تا فایل‌یابی، مذاکره و KPIها از داده واقعی تغذیه شوند.</span></div>`}</section>`}
