function beforeAfterPage(){const estimate=state.pkg==='gold'||state.pkg==='exclusive';return `${topIntro('BEFORE / AFTER','سیستم قبل و بعد','شخصی‌سازی خانه بر اساس علایق مشتری؛ در سطح طلایی، تخمین قیمت و ثبت سفارش نیز اضافه می‌شود.')}<div class="beforeafter" data-reveal><div class="room before" style="background-image:url('${imageUrls.before}')"><span>قبل</span></div><div class="transform">${icon('arrow')}</div><div class="room after" style="background-image:url('${imageUrls.after}')"><span>بعد</span></div></div><div class="panel" data-reveal><div class="panel-head"><div><h3>پروفایل ترجیحات مشتری</h3><small>پس از ورود اطلاعات مشتری</small></div><span class="status">آماده</span></div><div class="empty-state"><strong>هنوز ترجیحی ثبت نشده است.</strong><span>در نسخه نهایی، سلیقه و نیاز واقعی مشتری اینجا ثبت می‌شود و سپس برای طراحی Before / After استفاده خواهد شد.</span></div>${estimate?'<div class="estimate-box"><b>تخمین قیمت</b><strong>—</strong><small>پس از ورود مشخصات واقعی ملک و اتصال موتور قیمت‌گذاری محاسبه می‌شود.</small></div>':''}</div>`}
