function assistantPage(){return `${topIntro('MANAGEMENT AI','دستیار هوشمند مدیریتی','در نسخه نهایی، دستیار فقط بر اساس داده‌ها، گزارش‌ها و قواعد تأییدشده همین Workspace پاسخ می‌دهد.')}<div class="assistant-box panel" data-reveal><div class="assistant-title"><div class="ai-avatar">${icon('brain')}</div><div><h3>دستیار آماده اتصال</h3><small>بدون داده ساختگی</small></div></div><div class="empty-state"><strong>هنوز داده‌ای برای تحلیل وجود ندارد.</strong><span>پس از ورود فایل‌ها، بازدیدها و گزارش‌های واقعی، سؤال مدیریتی را از همین بخش بپرسید.</span></div><div class="chat-input"><input placeholder="مثلاً: وضعیت بازدیدهای این هفته چیست؟"/><button class="btn btn-primary" type="button" data-demo-toast>تحلیل</button></div></div>`}

