function tourPage(){const tourUrl="https://www.keypano.com/v/224d32ao6dp5s0-1784818434.html";return `${topIntro('360° EXPERIENCE','نمای ۳۶۰ درجه پیشرفته','تور Keypano را داخل خود پنل مشاهده و کنترل کن؛ اگر سرویس مقصد embedding را مسدود کند، همان تور با یک کلیک در صفحه اصلی Keypano باز می‌شود.')}<section class="tour-card embedded-tour" data-reveal><div class="tour-toolbar"><div><span class="live-badge"><i></i> LIVE 360</span><b>تور مجازی ملک · Keypano</b></div><div class="tour-actions"><button class="btn btn-ghost" type="button" data-tour-reload>↻ بارگذاری مجدد</button><a class="btn btn-primary" href="${tourUrl}" target="_blank" rel="noopener noreferrer">باز کردن تور ${icon('arrow')}</a></div></div><div class="tour-frame-wrap"><iframe title="Lucky Web 360 Tour" src="${tourUrl}" allow="fullscreen; autoplay; xr-spatial-tracking" allowfullscreen loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe><div class="tour-fallback"><div class="tour-fallback-icon">${icon('compass')}</div><strong>اگر تور داخل پنل نمایش داده نشد</strong><span>احتمالاً Keypano اتصال داخل iframe را از سمت سرویس مقصد محدود کرده است.</span><a class="btn btn-primary" href="${tourUrl}" target="_blank" rel="noopener noreferrer">باز کردن مستقیم تور</a></div></div><div class="tour-info"><h3>تجربه ۳۶۰ در Workspace</h3><p>Keypano قابلیت Share و Embed تور را ارائه می‌کند؛ نمایش داخل iframe به تنظیمات و هدرهای امنیتی خود سرویس مقصد وابسته است.</p><div class="tour-points"><span>نمای تعاملی</span><span>Hotspot</span><span>حرکت بین فضاها</span><span>Desktop / Mobile / VR</span></div></div></section>`}
function howItWorks(key){const map={rag:['دانش دفتر وارد می‌شود','سؤال یا درخواست دریافت می‌شود','اطلاعات مرتبط بازیابی و پاسخ مستند تولید می‌شود'],visits:['درخواست بازدید ثبت می‌شود','تقویم و ظرفیت مشاور بررسی می‌شود','تأیید، یادآوری و نتیجه بازدید ثبت می‌شود'],files:['فایل‌های واقعی وارد می‌شوند','شرایط جستجو با نیاز مشتری تطبیق داده می‌شود','فایل مرتبط برای پیگیری و گزارش ارائه می‌شود'],content:['ملک و هدف کمپین انتخاب می‌شود','سناریو و محتوای تصویری/ویدئویی تولید می‌شود','خروجی پس از تأیید آماده انتشار می‌شود'],beforeafter:['تصویر واقعی فضا و سلیقه مشتری دریافت می‌شود','سناریوی تغییر و طراحی پیشنهاد می‌شود','در سطوح مربوط، تخمین قیمت و ثبت سفارش انجام می‌شود'],seo:['وضعیت واقعی سایت و محتوا بررسی می‌شود','مشکلات فنی و محتوایی اولویت‌بندی می‌شوند','بهینه‌سازی و گزارش رشد دنبال می‌شود'],management:['اعضای واقعی و ساختار تیم ثبت می‌شوند','فعالیت‌ها و گزارش‌های روزانه جمع‌آوری می‌شوند','شاخص‌های عملکرد محاسبه می‌شوند'],assistant:['داده‌های مجاز Workspace در دسترس دستیار قرار می‌گیرد','سؤال مدیریتی تحلیل می‌شود','پاسخ با ارجاع به داده واقعی ارائه می‌شود'],automation:['رویداد از سیستم متصل دریافت می‌شود','قواعد کسب‌وکار اجرا می‌شوند','اقدام خودکار و نتیجه ثبت می‌شود'],persona:['هویت و لحن برند تعریف می‌شود','محتوا با شخصیت اختصاصی تولید می‌شود','خروجی در کانال‌های تعیین‌شده استفاده می‌شود'],'360pro':['تصاویر واقعی ملک دریافت می‌شوند','نقاط و مسیرهای تور تعریف می‌شوند','تور تعاملی برای مشتری منتشر می‌شود']};const steps=map[key]||['ورودی واقعی دریافت می‌شود','منطق سرویس روی داده اجرا می‌شود','نتیجه در Workspace ثبت می‌شود'];return `<section class="final-workflow panel" data-reveal><div class="panel-head"><div><span class="section-kicker">FINAL VERSION</span><h3>این بخش در نسخه نهایی چطور کار می‌کند؟</h3><small>این محیط Demo است؛ منطق اجرایی واقعی در مرحله اتصال Backend فعال می‌شود.</small></div></div><div class="workflow-steps">${steps.map((x,i)=>`<div class="workflow-step"><b>0${i+1}</b><span>${x}</span></div>`).join('')}</div></section>`}

function customizeModal(){return `<div class="modal-backdrop" id="customizeModal"><section class="modal-card customize-modal"><header><div><span class="section-kicker">CUSTOMIZE EXPERIENCE</span><h3>تجربه خودت را بساز</h3></div><button class="icon-button" data-close-customize>${icon('x')}</button></header><div class="customize-section"><b>پوسته</b><div class="choice-grid"><button data-set-theme="dark" class="choice ${state.theme==='dark'?'selected':''}">Dark <span></span></button><button data-set-theme="light" class="choice ${state.theme==='light'?'selected':''}">Light <span></span></button></div></div><div class="customize-section"><b>Layout</b><div class="layout-grid">${[['classic','Classic','Sidebar + Header'],['header','Header Navigation','Navigation در Header'],['compact','Compact','Sidebar Icon-only'],['minimal','Minimal','خلوت و متمرکز'],['detailed','Detailed','اطلاعات بیشتر'],['futuristic','Futuristic','آینده‌نگر']].map(x=>`<button class="layout-choice ${state.layout===x[0]?'selected':''}" data-set-layout="${x[0]}"><strong>${x[1]}</strong><small>${x[2]}</small></button>`).join('')}</div></div><div class="customize-section"><b>Sidebar</b><div class="choice-grid three"><button data-set-sidebar="expanded" class="choice ${state.sidebar==='expanded'?'selected':''}">Expanded<small>کامل با نام‌ها</small></button><button data-set-sidebar="collapsed" class="choice ${state.sidebar==='collapsed'?'selected':''}">Icon Only<small>با Hover باز می‌شود</small></button><button data-set-sidebar="hidden" class="choice ${state.sidebar==='hidden'?'selected':''}">Hidden<small>فقط با ☰ باز و بسته می‌شود</small></button></div></div></section></div>`}
