function loadingPage(){return `<div class="loading-page"><div class="loading-orb"></div><h2>فضای کاری در حال آماده‌سازی است</h2><p>داده‌های اختصاصی حساب شما در حال بارگذاری‌اند.</p><div class="skeleton-line"></div><div class="skeleton-line short"></div></div>`}
function clientModal(){return `<div class="modal-backdrop" id="clientModal"><section class="modal-card file-modal"><header><div><span class="section-kicker">CLIENT CRM</span><h3>افزودن مشتری</h3><small>اطلاعات واقعی مشتری را ثبت کنید تا در بازدید و مذاکره قابل انتخاب باشد.</small></div><button class="icon-button" type="button" data-close-client>${icon('x')}</button></header><form id="clientForm" class="property-form"><label>نام مشتری<input name="name" required placeholder="نام و نام خانوادگی"></label><div class="form-grid"><label>شماره تماس<input name="phone" placeholder="۰۹۱۲..."></label><label>بودجه<input name="budget" placeholder="مثلاً ۲۰ میلیارد"></label></div><label>نیاز / ترجیح مشتری<textarea name="requirements" rows="3" placeholder="محله، متراژ، تعداد خواب، سبک و..."></textarea></label><div class="form-actions"><button type="button" class="btn btn-ghost" data-close-client>انصراف</button><button type="submit" class="btn btn-primary">ثبت مشتری ${icon('plus')}</button></div></form></section></div>`}
function visitModal(){return `<div class="modal-backdrop" id="visitModal"><section class="modal-card file-modal"><header><div><span class="section-kicker">VISIT BOOKING</span><h3>افزودن بازدید</h3><small>تاریخ را شمسی وارد کن؛ سیستم آن را برای ذخیره استاندارد به میلادی تبدیل می‌کند.</small></div><button class="icon-button" type="button" data-close-visit>${icon('x')}</button></header><form id="visitForm" class="property-form"><div class="form-grid"><label>تاریخ شمسی<input name="jalali" required placeholder="۱۴۰۵/۰۷/۰۴" inputmode="numeric"></label><label>ساعت<input name="time" required type="time" value="12:00"></label></div><div class="form-grid"><label>ملک<select name="property_id"><option value="">انتخاب ملک</option>${state.properties.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></label><label>مشتری<select name="client_id"><option value="">انتخاب مشتری</option>${state.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label></div><label>توضیحات<textarea name="notes" rows="3" placeholder="یادداشت بازدید"></textarea></label><div class="form-actions"><button type="button" class="btn btn-ghost" data-close-visit>انصراف</button><button type="submit" class="btn btn-primary">ثبت بازدید ${icon('calendar')}</button></div></form></section></div>`}
function fileModal(){return `<div class="modal-backdrop" id="fileModal"><section class="modal-card file-modal"><header><div><span class="section-kicker">RAW DATA ENTRY</span><h3>افزودن فایل ملک</h3><small>این فرم برای ورود داده خام واقعی دفتر است؛ هیچ داده نمونه‌ای از قبل وارد نشده.</small></div><button class="icon-button" type="button" data-close-file>${icon('x')}</button></header><form id="propertyForm" class="property-form"><label>نام / عنوان ملک<input name="title" required placeholder="مثلاً آپارتمان ۱۵۰ متری"></label><div class="form-grid"><label>متراژ<input name="area" required placeholder="۱۵۰ متر"></label><label>قیمت<input name="price" required placeholder="۱۲ میلیارد"></label></div><label>وضعیت<select name="status"><option value="active">فعال</option><option value="negotiation">در مذاکره</option><option value="sold">فروخته شد</option></select></label><label>مشتری مذاکره<select name="client_id"><option value="">بدون مشتری</option>${state.clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><div class="form-actions"><button type="button" class="btn btn-ghost" data-close-file>انصراف</button><button type="submit" class="btn btn-primary">ثبت فایل ${icon('plus')}</button></div></form></section></div>`}

function openCatalog(){state.catalog=true;document.querySelector('[data-close-modal="catalog"]')?.classList.add('show')}
function closeCatalog(){state.catalog=false;document.querySelector('[data-close-modal="catalog"]')?.classList.remove('show')}
function toast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.innerHTML=`<span>${type==='success'?icon('check'):icon('x')}</span>${esc(message)}`;document.body.appendChild(el);requestAnimationFrame(()=>el.classList.add('show'));setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.remove(),300)},2600)}
function observeReveals(){const els=document.querySelectorAll('[data-reveal]');if(!('IntersectionObserver' in window)){els.forEach(x=>x.classList.add('revealed'));return}const io=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('revealed');io.unobserve(e.target)}}),{threshold:.08});els.forEach(x=>io.observe(x));document.querySelectorAll('[data-count]').forEach(el=>countUp(el,Number(el.dataset.count)));}
function countUp(el,target){if(el.dataset.done)return;el.dataset.done='1';const start=performance.now(),duration=900;const tick=t=>{const p=Math.min(1,(t-start)/duration),e=1-Math.pow(1-p,3);el.textContent=Math.round(target*e);if(p<1)requestAnimationFrame(tick)};requestAnimationFrame(tick)}

document.addEventListener('submit',e=>{if(e.target?.id!=='authForm')e.preventDefault()},true);

async function loadWorkspace(){
  if(!supabase)return;
  state.loading=true;render();
  try{
    const [{data:profile},{data:properties},{data:clients},{data:visits},{data:activity},{data:kpiRows}] = await Promise.all([
      supabase.from('lw_profiles').select('*').eq('id',state.session.user.id).maybeSingle(),
      supabase.from('lw_demo_properties').select('*').eq('user_id',state.session.user.id).order('created_at',{ascending:false}).limit(50),
      supabase.from('lw_clients').select('*').eq('user_id',state.session.user.id).order('created_at',{ascending:false}).limit(50),
      supabase.from('lw_visits').select('*').eq('user_id',state.session.user.id).order('scheduled_at',{ascending:true}).limit(50),
      supabase.from('lw_demo_activity').select('*').eq('user_id',state.session.user.id).order('created_at',{ascending:false}).limit(8),
      supabase.from('lw_dashboard_kpis').select('*').eq('user_id',state.session.user.id).maybeSingle()
    ]);
    state.profile=profile||{full_name:state.session.user.user_metadata?.full_name||'مدیر فضای کاری'};
    state.properties=properties||[]; state.clients=clients||[]; state.visits=visits||[];
    state.activity=(activity||[]).map(x=>[x.title,x.subtitle,x.relative_time]);
    if(kpiRows)state.kpis={properties:kpiRows.active_properties||0,visits:kpiRows.upcoming_visits||0,leads:kpiRows.active_leads||0,deals:kpiRows.closed_deals||0,pipeline:kpiRows.pipeline_value||0,conversion:kpiRows.conversion_rate||0}; else state.kpis={properties:(properties||[]).length,visits:0,leads:0,deals:0,pipeline:0,conversion:0};
    const uid=state.session.user.id;if(profile?.preferred_theme && !localStorage.getItem(`lw-theme-${uid}`))state.theme=profile.preferred_theme;if(profile?.layout_preference && !localStorage.getItem(`lw-layout-${uid}`))state.layout=profile.layout_preference;if(profile?.sidebar_preference && !localStorage.getItem(`lw-sidebar-${uid}`))state.sidebar=profile.sidebar_preference;
  }catch(e){toast('بارگذاری داده‌های فضای کاری ناموفق بود.','error');}
  finally{state.loading=false;render()}
}
function preferenceStorageKey(field){const uid=state.session?.user?.id||'guest';return ({preferred_theme:`lw-theme-${uid}`,layout_preference:`lw-layout-${uid}`,sidebar_preference:`lw-sidebar-${uid}`,package:`lw-package-${uid}`})[field]||`lw-${field}-${uid}`}
async function persistPreference(field,value){
  localStorage.setItem(preferenceStorageKey(field),value);
  if(!supabase||!state.session)return;
  try{await supabase.from('lw_profiles').update({[field]:value}).eq('id',state.session.user.id)}catch{}
}
async function logout(){if(supabase)await supabase.auth.signOut();state.session=null;state.profile=null;state.screen='landing';state.pkg=null;state.page='overview';toast('از حساب خارج شدید.');render()}

async function saveClient(e){e.preventDefault();const fd=new FormData(e.currentTarget);const row={name:String(fd.get('name')||'').trim(),phone:String(fd.get('phone')||'').trim()||null,budget:String(fd.get('budget')||'').trim()||null,requirements:String(fd.get('requirements')||'').trim()||null,status:'active'};if(!row.name)return toast('نام مشتری را وارد کنید.','error');const {data,error}=await supabase.from('lw_clients').insert({user_id:state.session.user.id,...row}).select().single();if(error){console.error(error);return toast('ثبت مشتری انجام نشد.','error')}state.clients=[data,...state.clients];e.currentTarget.reset();document.querySelector('#clientModal')?.classList.remove('show');toast('مشتری با موفقیت ثبت شد.');updateDashboardPage()}
async function saveVisit(e){e.preventDefault();const fd=new FormData(e.currentTarget);const raw=String(fd.get('jalali')||'').trim().replaceAll('-','/');const m=raw.match(/^(\d{4})[\/](\d{1,2})[\/](\d{1,2})$/);if(!m)return toast('تاریخ را به شکل ۱۴۰۵/۰۷/۰۴ وارد کنید.','error');const g=jalaliToGregorian(+m[1],+m[2],+m[3]);const time=String(fd.get('time')||'12:00');const iso=`${String(g.gy).padStart(4,'0')}-${String(g.gm).padStart(2,'0')}-${String(g.gd).padStart(2,'0')}T${time}:00`;const {data,error}=await supabase.from('lw_visits').insert({user_id:state.session.user.id,property_id:String(fd.get('property_id')||'')||null,client_id:String(fd.get('client_id')||'')||null,scheduled_at:iso,status:'scheduled',notes:String(fd.get('notes')||'').trim()||null}).select().single();if(error){console.error(error);return toast('ثبت بازدید انجام نشد.','error')}state.visits=[...state.visits,data].sort((a,b)=>new Date(a.scheduled_at)-new Date(b.scheduled_at));e.currentTarget.reset();document.querySelector('#visitModal')?.classList.remove('show');toast('بازدید با تاریخ ایرانی ثبت شد.');updateDashboardPage()}
async function updateProperty(id,patch){const {data,error}=await supabase.from('lw_demo_properties').update(patch).eq('id',id).eq('user_id',state.session.user.id).select().single();if(error){console.error(error);return toast('تغییر وضعیت ذخیره نشد.','error')}state.properties=state.properties.map(p=>p.id===id?data:p);toast('وضعیت ملک ذخیره شد.');updateDashboardPage()}
function bind(){document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>openAuth(b.dataset.auth,null));document.querySelectorAll('[data-go-dashboard]').forEach(b=>b.onclick=()=>{state.screen='dashboard';state.pkg=state.pkg||'bronze';state.page='overview';render();window.scrollTo({top:0})});document.querySelectorAll('[data-catalog]').forEach(b=>b.onclick=openCatalog);document.querySelectorAll('[data-close-catalog]').forEach(b=>b.onclick=closeCatalog);document.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=e=>{if(e.target===b){if(b.dataset.closeModal==='catalog')closeCatalog();if(b.dataset.closeModal==='auth')closeAuth()}});document.querySelectorAll('[data-pkg]').forEach(b=>b.onclick=()=>{state.pendingPkg=b.dataset.pkg;if(!state.session)openAuth('signup',b.dataset.pkg);else{state.pkg=b.dataset.pkg;localStorage.setItem(preferenceStorageKey('package'),state.pkg);state.screen='dashboard';state.page='overview';render();window.scrollTo({top:0})}});document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>{state.screen='landing';state.pkg=null;state.page='overview';render();window.scrollTo({top:0})});document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>{state.screen='landing';state.pkg=null;state.page='overview';render();window.scrollTo({top:0})});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(b.classList.contains('locked'))return toast('این قابلیت نیازمند ارتقای پکیج است.','error');state.page=b.dataset.page;updateDashboardPage();window.scrollTo({top:0,behavior:'smooth'})});document.querySelectorAll('[data-mobile]').forEach(b=>b.onclick=()=>document.querySelector('.sidebar')?.classList.toggle('open'));document.querySelector('.mobile-backdrop')?.addEventListener('click',()=>document.querySelector('.sidebar')?.classList.remove('open'));document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{state.pkg=b.dataset.upgrade;localStorage.setItem(preferenceStorageKey('package'),state.pkg);state.page='overview';updateDashboardPage();toast('سطح Demo برای مشاهده امکانات ارتقا یافت.')});document.querySelectorAll('[data-scroll]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.scroll)?.scrollIntoView({behavior:'smooth'}));document.querySelectorAll('[data-theme-toggle]').forEach(b=>b.onclick=async()=>{state.theme=state.theme==='dark'?'light':'dark';await persistPreference('preferred_theme',state.theme);updateThemeUI();b.classList.remove('theme-flip');void b.offsetWidth;b.classList.add('theme-flip')});document.querySelectorAll('[data-customize]').forEach(b=>b.onclick=()=>{document.querySelector('#customizeModal')?.classList.add('show');updateCustomizeUI()});document.querySelectorAll('[data-close-customize]').forEach(b=>b.onclick=()=>document.querySelector('#customizeModal')?.classList.remove('show'));document.querySelectorAll('[data-set-theme]').forEach(b=>b.onclick=async()=>{state.theme=b.dataset.setTheme;await persistPreference('preferred_theme',state.theme);updateThemeUI()});document.querySelectorAll('[data-set-layout]').forEach(b=>b.onclick=async()=>{state.layout=b.dataset.setLayout;await persistPreference('layout_preference',state.layout);applyChrome();updateCustomizeUI()});document.querySelectorAll('[data-set-sidebar]').forEach(b=>b.onclick=async()=>{state.sidebar=b.dataset.setSidebar;await persistPreference('sidebar_preference',state.sidebar);applyChrome();updateCustomizeUI()});document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>document.querySelector('#profileModal')?.classList.add('show'));document.querySelectorAll('[data-close-profile]').forEach(b=>b.onclick=()=>document.querySelector('#profileModal')?.classList.remove('show'));document.querySelectorAll('[data-logout]').forEach(b=>b.onclick=logout);document.querySelectorAll('.modal-backdrop').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('show')}));document.querySelectorAll('[data-banner-prev]').forEach(b=>b.onclick=()=>setBanner(state.landingBanner-1));document.querySelectorAll('[data-banner-next]').forEach(b=>b.onclick=()=>setBanner(state.landingBanner+1));document.querySelectorAll('[data-banner-dot]').forEach(b=>b.onclick=()=>setBanner(Number(b.dataset.bannerDot)));document.querySelectorAll('[data-add-file]').forEach(b=>b.onclick=()=>document.querySelector('#fileModal')?.classList.add('show'));document.querySelectorAll('[data-close-file]').forEach(b=>b.onclick=()=>document.querySelector('#fileModal')?.classList.remove('show'));document.querySelectorAll('#propertyForm').forEach(f=>f.onsubmit=saveProperty);document.querySelectorAll('[data-add-client]').forEach(b=>b.onclick=()=>document.querySelector('#clientModal')?.classList.add('show'));document.querySelectorAll('[data-close-client]').forEach(b=>b.onclick=()=>document.querySelector('#clientModal')?.classList.remove('show'));document.querySelectorAll('#clientForm').forEach(f=>f.onsubmit=saveClient);document.querySelectorAll('[data-add-visit]').forEach(b=>b.onclick=()=>document.querySelector('#visitModal')?.classList.add('show'));document.querySelectorAll('[data-close-visit]').forEach(b=>b.onclick=()=>document.querySelector('#visitModal')?.classList.remove('show'));document.querySelectorAll('#visitForm').forEach(f=>f.onsubmit=saveVisit);document.querySelectorAll('[data-property-status]').forEach(el=>el.onchange=e=>updateProperty(e.target.dataset.propertyStatus,{status:e.target.value}));document.querySelectorAll('[data-property-client]').forEach(el=>el.onchange=e=>updateProperty(e.target.dataset.propertyClient,{client_id:e.target.value||null}));document.querySelectorAll('[data-divar]').forEach(b=>b.onclick=()=>toast('اتصال دیوار نیازمند دسترسی معتبر/API است؛ صف اتصال آماده است.'));document.querySelectorAll('[data-tour-reload]').forEach(b=>b.onclick=()=>{const f=document.querySelector('.tour-frame-wrap iframe');if(f){f.src=f.src;document.querySelector('.tour-fallback')?.classList.remove('show')}});document.querySelectorAll('.tour-frame-wrap iframe').forEach(f=>f.addEventListener('error',()=>f.closest('.tour-frame-wrap')?.querySelector('.tour-fallback')?.classList.add('show')));document.querySelectorAll('[data-demo-toast]').forEach(b=>b.onclick=()=>toast('این بخش در نسخه Demo نمایشی است و پس از اتصال داده واقعی فعال می‌شود.'))}
function setBanner(index){const slides=[...document.querySelectorAll('.banner-slide')];if(!slides.length)return;state.landingBanner=(index+slides.length)%slides.length;slides.forEach((x,i)=>x.classList.toggle('active',i===state.landingBanner));document.querySelectorAll('[data-banner-dot]').forEach((d,i)=>d.classList.toggle('active',i===state.landingBanner))}

async function saveProperty(e){e.preventDefault();const form=e.currentTarget;const fd=new FormData(form);const row={title:String(fd.get('title')||'').trim(),area:String(fd.get('area')||'').trim(),price:String(fd.get('price')||'').trim(),status:String(fd.get('status')||'active'),client_id:String(fd.get('client_id')||'')||null};if(!row.title||!row.area||!row.price)return toast('عنوان، متراژ و قیمت را وارد کنید.','error');if(!supabase||!state.session)return toast('حساب کاربری به Supabase متصل نیست.','error');const {data,error}=await supabase.from('lw_demo_properties').insert({user_id:state.session.user.id,...row}).select().single();if(error){console.error(error);return toast('ثبت فایل انجام نشد.','error')}state.properties=[data,...state.properties];form.reset();document.querySelector('#fileModal')?.classList.remove('show');toast('فایل با موفقیت به Workspace شما اضافه شد.');if(state.page==='files')updateDashboardPage()}

(async function boot(){if(supabase){const {data}=await supabase.auth.getSession();if(data.session){state.session=data.session;const uid=data.session.user.id;state.theme=localStorage.getItem(`lw-theme-${uid}`)||state.theme;state.layout=localStorage.getItem(`lw-layout-${uid}`)||state.layout;state.sidebar=localStorage.getItem(`lw-sidebar-${uid}`)||state.sidebar;state.pkg=localStorage.getItem(`lw-package-${uid}`)||'bronze';state.screen='dashboard';await loadWorkspace();return}supabase.auth.onAuthStateChange((_event,session)=>{state.session=session})}render()})();
